package net.minecraft.world.item.component;import java.util.*;public class CustomData{public static final CustomData EMPTY=new CustomData(new Tag());final Tag t;CustomData(Tag t){this.t=t;}public Tag copyTag(){Tag n=new Tag();n.m.putAll(t.m);return n;}public static CustomData of(Tag t){return new CustomData(t);}public static class Tag{public Map<String,Integer> m=new HashMap<>();public int getInt(String k){return m.getOrDefault(k,0);}public void putInt(String k,int n){m.put(k,n);}}}